import re

def extract_name(desc):
    # Take everything before the first verb like specializes/provides/is/harnesses/offers/operates/develops/manufactures
    m = re.match(r'^(.*?)(?:\s+(?:specializes|provides|is|harnesses|offers|operates|develops|manufactures|focuses|engages|produces|delivers|designs|markets|invests|serves)\b)', desc)
    if m:
        name = m.group(1).strip()
        # Strip trailing comma-clauses like ", based in Canada,"
        name = re.sub(r',\s*based.*$', '', name)
        return name.rstrip(',').strip()
    return desc.split('.')[0].strip()

